<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'
import { t } from '@/i18n'
import { resolveIcon } from '@/utils/iconRegistry'
import PosterImage from './PosterImage.vue'
import type { Job, Poster } from './types'

const props = defineProps<{ jobs: Job[]; productName: string; poster: (job: Job) => Poster | null; busy: boolean }>()
const emit = defineEmits<{ retry: [job: Job]; edit: [job: Job]; download: [job: Job]; remove: [job: Job]; check: [job: Job]; saveAsset: [job: Job]; reuse: [job: Job]; refresh: []; downloadAll: []; preview: [job: Job] }>()
const filter = ref('all')
const newest = ref(true)
const selectedId = ref(0)
// Keep the record list unobstructed until the user asks for more context.
const detailOpen = ref(false)
const fullPrompt = ref(false)
const visible = computed(() => props.jobs.filter(job => filter.value === 'all' || job.mode === filter.value).slice().sort((a, b) => (newest.value ? -1 : 1) * (a.create_time.localeCompare(b.create_time) || a.id - b.id)))
const selected = computed(() => visible.value.find(job => job.id === selectedId.value) || visible.value[0])
const groups = computed(() => {
  const result: { date: string; jobs: Job[] }[] = []
  for (const job of visible.value) {
    const date = job.create_time.slice(0, 10)
    let group = result[result.length - 1]
    if (!group || group.date !== date) { group = { date, jobs: [] }; result.push(group) }
    group.jobs.push(job)
  }
  return result
})
watch(selected, () => { fullPrompt.value = false })
function kind(job: Job) { return job.mode === 'video' ? t('视频') : ({ main: t('主图'), hero: t('主图'), detail: t('详情图'), full: t('详情图'), poster: t('海报'), tryon: t('试穿图') } as Record<string, string>)[job.request.creative_goal || ''] || t('图片') }
function status(job: Job) { return ({ queued: job.provider_submitted ? t('生成中') : t('等待生成'), running: t('生成中'), success: t('已完成'), failed: t('生成失败'), unknown: t('待核对'), cancelled: t('已取消') })[job.status] }
function dateLabel(value: string) { return new Date(value + 'T00:00:00').toLocaleDateString('zh-CN', { month: 'long', day: 'numeric' }) }
function select(job: Job) { selectedId.value = job.id; detailOpen.value = true }
function closeOnEscape(event: KeyboardEvent) { if (event.key === 'Escape' && detailOpen.value) detailOpen.value = false }
const userPrompt = computed(() => {
  const snapshot = selected.value?.request.original.ui_snapshot as { userPrompt?: string } | undefined
  return snapshot?.userPrompt || ''
})
async function copyPrompt() {
  if (!selected.value) return
  try { await navigator.clipboard.writeText(selected.value.request.prompt); ElMessage.success(t('提示词已复制')) } catch { ElMessage.error(t('复制失败，请手动选择提示词')) }
}
onMounted(() => window.addEventListener('keydown', closeOnEscape))
onBeforeUnmount(() => window.removeEventListener('keydown', closeOnEscape))
</script>

<template>
  <div class="history-workspace">
    <main class="history-pane">
      <header class="history-heading"><div><h2>{{ t('生成记录') }}</h2><span>{{ t('{count} 项作品', { count: jobs.length }) }}</span></div><el-button text :icon="resolveIcon('Refresh')" :aria-label="t('刷新')" @click="emit('refresh')" /></header>
      <div class="history-controls"><div class="history-tabs" role="tablist" :aria-label="t('作品类型')"><button v-for="tab in [{ id: 'all', name: t('全部') }, { id: 'image', name: t('图片') }, { id: 'video', name: t('视频') }]" :key="tab.id" role="tab" :aria-selected="filter === tab.id" :class="{ active: filter === tab.id }" @click="filter = tab.id">{{ tab.name }}</button></div><el-button class="sort-button" :icon="resolveIcon(newest ? 'SortDown' : 'SortUp')" @click="newest = !newest">{{ newest ? t('按时间倒序') : t('按时间正序') }}</el-button></div>
      <div v-if="!visible.length" class="history-empty"><el-icon :size="42"><component :is="resolveIcon('Picture')" /></el-icon><h3>{{ jobs.length ? t('暂无此类作品') : t('开始这个商品的第一次创作') }}</h3><p>{{ t('生成的图片和视频会按时间保存在这里') }}</p></div>
      <section v-for="group in groups" :key="group.date" class="history-day"><h3>{{ dateLabel(group.date) }}</h3><div class="history-list"><article v-for="job in group.jobs" :key="job.id" class="history-item job-tile" :class="[job.status, { selected: selected?.id === job.id && detailOpen }]">
        <button class="history-select" type="button" :aria-label="t('查看{title}', { title: job.title })" @click="select(job)"><div class="history-thumbnail"><PosterImage v-if="job.status === 'success' && job.mode === 'image'" :src="job.result_url" :poster="poster(job)" :alt="job.title" /><video v-else-if="job.status === 'success'" :src="job.result_url" preload="metadata" /><el-icon v-else :size="24" :class="{ 'is-loading': job.status === 'running' }"><component :is="resolveIcon(job.status === 'running' ? 'Loading' : ['failed','unknown'].includes(job.status) ? 'Warning' : 'Clock')" /></el-icon><span class="thumbnail-label">{{ kind(job) }}</span><span v-if="job.mode === 'video'" class="thumbnail-play"><el-icon><component :is="resolveIcon('VideoPlay')" /></el-icon></span></div><div class="history-item-content"><strong>{{ job.title }}</strong><time><el-icon><component :is="resolveIcon('Clock')" /></el-icon>{{ job.create_time.slice(5,16) }}</time><div class="record-badges"><span class="kind-badge">{{ kind(job) }}</span><span class="status-badge" :class="job.status">{{ status(job) }}</span></div><p v-if="job.error_message" class="record-error">{{ job.error_message }}</p></div></button>
        <el-dropdown trigger="click" class="record-menu"><el-button text :icon="resolveIcon('MoreFilled')" :aria-label="t('更多操作')" /><template #dropdown><el-dropdown-menu><el-dropdown-item @click="select(job)">{{ t('作品详情') }}</el-dropdown-item><el-dropdown-item v-if="['success','failed'].includes(job.status)" :disabled="busy" @click="emit('retry', job)">{{ t('重新生成') }}</el-dropdown-item><el-dropdown-item v-if="['success','failed','cancelled'].includes(job.status)" divided @click="emit('remove', job)">{{ t('删除成品') }}</el-dropdown-item></el-dropdown-menu></template></el-dropdown>
      </article></div></section>
      <div v-if="visible.some(job => job.status === 'success')" class="history-download"><el-button link :icon="resolveIcon('Download')" @click="emit('downloadAll')">{{ t('打包下载') }}</el-button></div>
    </main>
    <Transition name="details-backdrop-fade"><button v-if="detailOpen" type="button" class="details-backdrop" :aria-label="t('关闭作品详情')" @click="detailOpen = false" /></Transition>
    <Transition name="details-drawer">
    <aside v-if="detailOpen" class="artwork-details" role="dialog" aria-modal="true" :aria-label="t('作品详情')">
      <header class="detail-heading"><h2>{{ t('作品详情') }}</h2><el-button text :icon="resolveIcon('Close')" :aria-label="t('关闭作品详情')" @click="detailOpen = false" /></header>
      <template v-if="selected">
        <div class="detail-scroll">
          <button type="button" class="detail-preview" :disabled="selected.status !== 'success'" :aria-label="t('预览{title}', { title: selected.title })" @click="emit('preview', selected)"><PosterImage v-if="selected.status === 'success' && selected.mode === 'image'" :src="selected.result_url" :poster="poster(selected)" :alt="selected.title" large /><video v-else-if="selected.status === 'success'" :src="selected.result_url" preload="metadata" /><div v-else class="detail-placeholder"><el-icon :size="30"><component :is="resolveIcon('Picture')" /></el-icon><span>{{ status(selected) }}</span></div><span class="preview-tags"><span class="kind-badge">{{ kind(selected) }}</span><span class="status-badge" :class="selected.status">{{ status(selected) }}</span></span></button>
          <p v-if="selected.error_message" class="detail-error">{{ selected.error_message }}</p>
          <section class="detail-section"><div class="detail-section-heading"><h3>{{ t('本次提示词') }}</h3><el-button link :icon="resolveIcon('CopyDocument')" @click="copyPrompt">{{ t('复制') }}</el-button></div><p class="prompt-box" :class="{ expanded: fullPrompt }">{{ userPrompt || selected.request.prompt }}</p><el-button link class="prompt-expand" @click="fullPrompt = !fullPrompt">{{ fullPrompt ? t('收起完整提示词') : t('查看完整提示词') }}</el-button><pre v-if="fullPrompt" class="full-prompt">{{ selected.request.prompt }}</pre></section>
          <section class="detail-section"><h3>{{ t('参考图') }}</h3><div v-if="selected.request.images.length" class="detail-references"><button v-for="(src, index) in selected.request.images" :key="index" type="button" @click="emit('preview', { ...selected, mode: 'image', result_url: src, title: t('参考图 {count}', { count: index + 1 }), request: { ...selected.request, original: {} } })"><img :src="src" :alt="t('参考图 {count}', { count: index + 1 })" /><span>{{ t('参考图 {count}', { count: index + 1 }) }}</span></button></div><p v-else class="detail-muted">{{ t('本次未使用参考图') }}</p><p v-if="selected.request.images.length" class="detail-muted">{{ t('已使用 {count} 张参考图', { count: selected.request.images.length }) }}</p></section>
          <section class="detail-section"><h3>{{ t('生成参数') }}</h3><dl class="parameter-table"><div><dt>{{ t('生成模型') }}</dt><dd>{{ selected.request.model_id || t('历史记录未保存') }}</dd></div><div><dt>{{ t('尺寸比例') }}</dt><dd>{{ selected.request.options.size || selected.request.options.aspect_ratio || '—' }}</dd></div><div v-if="selected.request.options.resolution"><dt>{{ t('清晰度') }}</dt><dd>{{ selected.request.options.resolution }}</dd></div><div v-if="selected.mode === 'video'"><dt>{{ t('视频时长') }}</dt><dd>{{ t('{count} 秒', { count: selected.request.options.duration }) }}</dd></div><div><dt>{{ t('生成时间') }}</dt><dd>{{ selected.create_time.slice(0,16) }}</dd></div></dl></section>
          <div v-if="selected.status === 'success'" class="detail-utilities"><el-button link :icon="resolveIcon('Download')" @click="emit('download', selected)">{{ t('下载') }}</el-button><el-button v-if="selected.mode === 'image'" link :icon="resolveIcon('EditPen')" @click="emit('edit', selected)">{{ t('改图') }}</el-button><el-button v-if="selected.mode === 'image'" link :icon="resolveIcon('FolderAdd')" @click="emit('saveAsset', selected)">{{ t('保存至资产') }}</el-button></div>
        </div>
        <footer class="detail-footer"><el-button v-if="selected.request.original.ui_snapshot" :disabled="busy" :icon="resolveIcon('CopyDocument')" @click="emit('reuse', selected)">{{ t('复用配置') }}</el-button><el-button v-if="['success','failed'].includes(selected.status)" type="primary" :disabled="busy" :icon="resolveIcon('RefreshRight')" @click="emit('retry', selected)">{{ t('重新生成') }}</el-button><el-button v-if="['unknown','failed'].includes(selected.status)" :disabled="busy" @click="emit('check', selected)">{{ t('核对原任务') }}</el-button></footer>
      </template>
      <div v-else class="detail-empty"><el-icon :size="34"><component :is="resolveIcon('Document')" /></el-icon><p>{{ t('选择作品查看生成详情') }}</p></div>
    </aside>
    </Transition>
  </div>
</template>

<style scoped>
.history-workspace { position: relative; display: block; min-width: 0; min-height: 0; overflow: hidden; }.history-pane { min-height: 0; min-width: 0; height: 100%; overflow-y: auto; padding: 22px 22px 35px; scrollbar-gutter: stable; }.history-heading,.detail-heading { display: flex; align-items: center; justify-content: space-between; gap: 10px; }.history-heading > div { display: flex; align-items: baseline; gap: 12px; }.history-heading h2,.detail-heading h2 { margin: 0; font-size: 17px; font-weight: 600; }.history-heading span { font-size: 11px; color: #7297c8; }.history-controls { display: flex; justify-content: space-between; align-items: center; gap: 8px; margin: 12px 0 22px; }.history-tabs { display: flex; padding: 2px; border: 1px solid #182c49; background: #0b182a; border-radius: 22px; }.history-tabs button { border: 0; background: transparent; color: #92afd2; padding: 7px 17px; border-radius: 20px; font: inherit; font-size: 12px; cursor: pointer; }.history-tabs button.active { color: white; background: linear-gradient(110deg,#3160ff,#5553ff); }.sort-button { font-size: 11px; padding: 8px 10px; }.history-day { margin: 0 0 25px; }.history-day > h3 { font-size: 14px; color: #9dc5f5; margin: 0 0 11px; font-weight: 500; }.history-list { display: flex; flex-direction: column; gap: 10px; }.history-item { position: relative; border: 1px solid #1a304e; border-radius: 9px; background: linear-gradient(125deg,rgba(16,35,62,.74),rgba(10,24,42,.72)); transition: border-color .15s; }.history-item.selected { border-color: #467eff; box-shadow: inset 0 0 0 1px #3166ed; }.history-select { display: flex; align-items: center; gap: 17px; width: 100%; padding: 7px 38px 7px 8px; background: none; border: 0; font: inherit; color: inherit; text-align: left; cursor: pointer; }.history-thumbnail { position: relative; width: 114px; height: 100px; overflow: hidden; border-radius: 6px; flex-shrink: 0; background: #0a1321; display: grid; place-items: center; color: #6991c4; }.history-thumbnail :deep(img),.history-thumbnail :deep(canvas),.history-thumbnail :deep(.poster-image),.history-thumbnail video { width: 100%; height: 100%; object-fit: cover; }.thumbnail-label { position: absolute; bottom: 6px; left: 6px; background: #4864ff; color: white; font-size: 10px; padding: 3px 6px; border-radius: 4px; }.thumbnail-play { position: absolute; inset: 0; display: grid; place-items: center; color: white; font-size: 23px; }.history-item-content { min-width: 0; padding: 4px 0; }.history-item-content > strong { display: block; font-size: 13px; font-weight: 500; color: #e1edff; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.history-item-content time { display: flex; align-items: center; gap: 5px; font-size: 11px; color: #83a9da; margin: 10px 0; }.record-badges { display: flex; gap: 8px; }.kind-badge,.status-badge { display: inline-flex; padding: 3px 10px; border-radius: 12px; font-size: 10px; background: #15234c; color: #a6adff; }.status-badge { color: #8fb6df; background: #10273c; }.status-badge.success { color: #4edbd0; background: #0b343c; }.status-badge.failed,.status-badge.unknown { color: #ffd482; background: #44351c; }.record-menu { position: absolute; right: 6px; top: 6px; }.record-menu :deep(.el-button) { color: #8ab9ee; padding: 6px; }.record-error { margin: 6px 0 0; max-width: 260px; font-size: 10px; color: #d99c9c; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.history-empty { height: 65%; min-height: 260px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 12px; color: #45628a; text-align: center; }.history-empty h3 { font-size: 15px; margin: 4px 0 0; color: #a4bcdd; }.history-empty p { margin: 0; font-size: 12px; color: #6b86aa; }.history-download { text-align: right; }.details-backdrop { position: absolute; inset: 0; z-index: 10; border: 0; padding: 0; background: rgba(2,8,18,.56); cursor: default; }.artwork-details { position: absolute; inset: 0 0 0 auto; z-index: 11; width: min(480px, calc(100% - 28px)); min-width: 0; min-height: 0; display: flex; flex-direction: column; border-left: 1px solid #2b4b72; background: #081322; box-shadow: -20px 0 44px rgba(0,0,0,.34); }.details-drawer-enter-active,.details-drawer-leave-active { transition: transform .22s ease; }.details-drawer-enter-from,.details-drawer-leave-to { transform: translateX(100%); }.details-backdrop-fade-enter-active,.details-backdrop-fade-leave-active { transition: opacity .18s ease; }.details-backdrop-fade-enter-from,.details-backdrop-fade-leave-to { opacity: 0; }.detail-heading { padding: 17px 20px 12px; }.detail-scroll { overflow-y: auto; scrollbar-gutter: stable; flex: 1; padding: 0 20px; min-height: 0; }.detail-preview { position: relative; display: block; padding: 0; width: 100%; aspect-ratio: 1.45; background: #0b1728; border: 1px solid #263b55; border-radius: 8px; overflow: hidden; cursor: pointer; }.detail-preview :deep(.poster-image),.detail-preview :deep(img),.detail-preview :deep(canvas),.detail-preview video { width: 100%; height: 100%; object-fit: contain; }.detail-placeholder { display: flex; align-items: center; justify-content: center; height: 100%; flex-direction: column; gap: 12px; color: #7c9bc0; }.preview-tags { position: absolute; bottom: 10px; left: 10px; display: flex; gap: 8px; }.preview-tags .kind-badge { background: #4669ff; color: white; }.detail-section { border-bottom: 1px solid #14253d; padding: 19px 0; }.detail-section h3 { font-size: 13px; font-weight: 500; margin: 0 0 12px; }.detail-section-heading { display: flex; align-items: baseline; justify-content: space-between; }.prompt-box,.full-prompt { white-space: pre-wrap; overflow-wrap: anywhere; font: inherit; font-size: 12px; line-height: 1.8; color: #adc7ea; padding: 11px 12px; margin: 0; border: 1px solid #233c61; background: linear-gradient(130deg,#0c1a2e,#10213b); border-radius: 7px; }.prompt-box { display: -webkit-box; -webkit-line-clamp: 4; -webkit-box-orient: vertical; overflow: hidden; }.prompt-box.expanded { -webkit-line-clamp: unset; }.prompt-expand { margin-top: 8px; font-size: 11px; }.full-prompt { margin-top: 10px; max-height: 330px; overflow-y: auto; }.detail-references { display: flex; gap: 9px; flex-wrap: wrap; }.detail-references button { display: flex; flex-direction: column; gap: 5px; align-items: center; border: 1px solid #1f3657; border-radius: 6px; background: #0c1a2e; padding: 6px; color: #8babd4; font-size: 10px; cursor: pointer; }.detail-references img { width: 63px; height: 57px; object-fit: contain; border-radius: 3px; }.detail-muted { font-size: 11px; color: #7394bd; margin: 9px 0 0; }.parameter-table { margin: 0; padding: 10px 12px; background: #0b192c; border: 1px solid #203755; border-radius: 7px; }.parameter-table > div { display: grid; grid-template-columns: 82px minmax(0,1fr); gap: 8px; padding: 6px 0; font-size: 11px; }.parameter-table dt { color: #7297c9; }.parameter-table dd { margin: 0; color: #c0d7f4; overflow-wrap: anywhere; }.detail-footer { display: flex; gap: 8px; flex-wrap: wrap; padding: 15px 20px; border-top: 1px solid #1c3150; }.detail-footer .el-button { flex: 1; margin: 0; font-size: 12px; }.detail-utilities { display: flex; flex-wrap: wrap; gap: 12px; padding: 16px 0; }.detail-utilities .el-button { margin: 0; font-size: 11px; }.detail-error { color: #fda4af; line-height: 1.7; font-size: 12px; }.detail-empty { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 12px; color: #5c7da9; font-size: 12px; }button:focus-visible { outline: 2px solid #79adff; outline-offset: 3px; }

@media (max-width: 900px) { .history-workspace { min-height: 530px; overflow: visible; }.history-pane { overflow: visible; padding: 20px 16px; }.details-backdrop { position: fixed; z-index: 2190; }.artwork-details { position: fixed; inset: 0 0 0 auto; width: min(460px,100vw); z-index: 2200; box-shadow: -18px 0 40px #0008; }.detail-scroll { padding: 0 20px; }.detail-preview { max-height: 35vh; }.history-thumbnail { width: 91px; height: 91px; }.history-select { gap: 12px; }.history-tabs button { padding: 7px 14px; } }
/* Actions are quiet controls, not pill-shaped badges. */
.history-download :deep(.el-button), .detail-utilities :deep(.el-button), .detail-footer :deep(.el-button) { min-height: 32px; padding: 7px 12px; border: 1px solid #2a486d; border-radius: 7px; color: #a9c9ef; background: #0c1b2f; font-weight: 500; transition: color .16s ease, border-color .16s ease, background .16s ease, transform .16s ease; }
.history-download :deep(.el-button:hover), .detail-utilities :deep(.el-button:hover), .detail-footer :deep(.el-button:hover) { color: #f0f7ff; border-color: #4c87c5; background: #132b48; transform: translateY(-1px); }
</style>
